"""Create exploratory charts from outputs generated by analyze.py."""
import argparse
from pathlib import Path
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

def visualize(directory: Path, destination: Path) -> list[Path]:
    monthly = pd.read_csv(directory / "monthly_sales.csv")
    products = pd.read_csv(directory / "top_products.csv")
    countries = pd.read_csv(directory / "country_sales.csv")
    customers = pd.read_csv(directory / "customer_summary.csv")
    destination.mkdir(parents=True, exist_ok=True)
    saved = []
    def save(name):
        path = destination / name
        plt.tight_layout()
        plt.savefig(path, dpi=180, bbox_inches="tight")
        plt.close()
        saved.append(path)
    if not monthly.empty:
        monthly = monthly.sort_values("Month")
        plt.figure(figsize=(10, 5))
        plt.plot(monthly["Month"].astype(str), monthly["Revenue"], marker="o")
        plt.title("Monthly gross sales (returns excluded)")
        plt.ylabel("Gross sales (GBP for UCI source)")
        plt.xticks(rotation=45, ha="right")
        save("monthly_sales.png")
    if not products.empty:
        top = products.nlargest(10, "Revenue").iloc[::-1]
        labels = top["Description"].fillna(top["StockCode"]).astype(str).str.slice(0, 35)
        plt.figure(figsize=(9, 6))
        plt.barh(labels, top["Revenue"])
        plt.title("Top 10 products by gross sales")
        plt.xlabel("Gross sales (GBP for UCI source)")
        save("top_products.png")
    if not countries.empty:
        top = countries.nlargest(10, "Revenue").iloc[::-1]
        plt.figure(figsize=(9, 5))
        plt.barh(top["Country"].fillna("Unknown").astype(str), top["Revenue"])
        plt.title("Top 10 countries by gross sales")
        plt.xlabel("Gross sales (GBP for UCI source)")
        save("country_sales.png")
    if not customers.empty:
        repeats = int(customers["RepeatCustomer"].astype(bool).sum())
        plt.figure(figsize=(6, 4))
        plt.bar(["Single order", "Repeat customer"], [len(customers)-repeats, repeats])
        plt.title("Known customers by number of orders")
        plt.ylabel("Number of customers")
        save("repeat_customers.png")
    return saved

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", type=Path, default=Path("outputs"))
    parser.add_argument("--output", type=Path, default=Path("outputs/charts"))
    args = parser.parse_args()
    for path in visualize(args.input, args.output):
        print(path)
